        self.connected = false
        self.ws = nil
        self.clientActive = false
        self.log("WebSocket closed by relay (%s) after %ds, will reconnect",
            reason, self.connectedAt > 0 and math.floor((self.closedAt - self.connectedAt) / 1000) or 0)
