    local entry = self:addDelivery({
        kind = kind,
        name = name,
        container = container.name,
        containerKind = self.Util.kindOfDef(container),
        remaining = count,
        total = count,
        processName = processName,
        createdAt = os.epoch("utc"),
    })
    return true, {
