        out[#out + 1] = {
            id = delivery.id,
            kind = delivery.kind,
            name = delivery.name,
            remaining = delivery.remaining or 0,
            total = delivery.total or 0,
            container = delivery.container,
            processName = delivery.processName,
            lastError = delivery.lastError,
        }
    end
    return out
end

return Recipe
