local M = {}


function M.deepcopy(value, seen)
    if type(value) ~= "table" then
        return value
    end
    seen = seen or {}
    if seen[value] then
        return seen[value]
    end
    local copy = {}
    seen[value] = copy
    for k, v in pairs(value) do
        copy[M.deepcopy(k, seen)] = M.deepcopy(v, seen)
    end
    return copy
end


function M.now()
    return os.epoch("utc")
end


function M.clamp(v, lo, hi)
    v = tonumber(v) or 0
    if v < lo then
        return lo
    end
    if v > hi then
        return hi
    end
    return v
end


function M.num(v, default)
    v = tonumber(v)
    if v == nil then
        return default
    end
    return v
end


function M.int(v, default)
    v = tonumber(v)
    if v == nil then
        return default
    end
    return math.floor(v)
end


function M.trim(s)
    if type(s) ~= "string" then
        return ""
    end
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end





function M.kindOfDef(def)
    local kind = type(def) == "table" and def.kind or def
    return kind == "fluid" and "fluid" or "item"
end


function M.count(t)
    local n = 0
    for _ in pairs(t or {}) do
        n = n + 1
    end
    return n
end




local LOG_LIMIT = 200
local logBuffer = {}
local logSeq = 0
local logHandler = nil


function M.setLogHandler(fn)
    logHandler = fn
end


function M.pushLog(prefix, text)
    logSeq = logSeq + 1
    local line = "[" .. (prefix or "IFM") .. "] " .. tostring(text)
    logBuffer[#logBuffer + 1] = { seq = logSeq, line = line }
    while #logBuffer > LOG_LIMIT do
        table.remove(logBuffer, 1)
    end
    if logHandler then
        pcall(logHandler, line, logSeq)
    end
end


function M.logSince(seq)
    local from = tonumber(seq) or 0
    local out = {}
    for _, entry in ipairs(logBuffer) do
        if entry.seq > from then
            out[#out + 1] = entry.line
        end
    end
    return out, logSeq
end


function M.makeLogger(prefix, enabled)
    return function(fmt, ...)
        if enabled == false then
            return
        end
        local msg
        if select("#", ...) > 0 then
            local ok, formatted = pcall(string.format, fmt, ...)
            if ok then
                msg = formatted
            else
                msg = tostring(fmt)
            end
        else
            msg = tostring(fmt)
        end
        M.pushLog(prefix, msg)
    end
end


local uidCounter = 0
function M.uid()
    uidCounter = uidCounter + 1
    return string.format("%x-%x", os.epoch("utc") % 0xFFFFFF, uidCounter % 0xFFFF)
end

return M
