        local seen = {}
        local count = 0
        for _, entry in ipairs(containers:filterResources(def.name)) do
            count = count + entry.count
            local key = entry.kind .. ":" .. entry.name
            if not seen[key] then
                seen[key] = true
                samples[#samples + 1] = { kind = entry.kind, name = entry.name }
            end
        end
        list[#list + 1] = {
            kind = "filter",
            name = def.name,
